//! 🟰️ Intrinsic equality composes the existing typed record and sequence cursors over original immutable fields.
use semio_framework_value_intrinsic::{DslValue,Number};
use crate::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetirementDemand,ValueError,ValueRefusalKind};
use crate::{RetainedEquality,RetainedEqualityCursor,RetainedEqualityFields,RetainedRecordEquality,RetainedEqualityElement};
use crate::retained_equality::{RetainedInlineEquality,RetainedEqualityBirth,equality_box,equality_box_work};
use std::mem::size_of;
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original intrinsic equality changed its source or field")}
fn permits(g:RetainedCloneGrant,d:RetirementDemand)->bool{g.maximum_items>0&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes&&g.maximum_depth>=d.depth}
unsafe impl RetainedEquality for Number{
 type Equality=RetainedInlineEquality<Self>;
 const CURSOR_BIRTH_WORK:u64=2;
 const INLINE_PAIR_BYTES:Option<usize>=Some(size_of::<Self>()*2);
 const INLINE_PAIR_WORK:Option<u64>=Some(<Self as RetainedEqualityElement>::WORK);
 fn equality_cursor()->Self::Equality{RetainedInlineEquality::new()}
 fn inline_equal(left:&Self,right:&Self)->Option<bool>{Some(left==right)}
 fn native_inline()->Option<crate::retained_equality::RetainedInlineWitness<Self>>{Some(crate::retained_equality::RetainedInlineWitness::new())}
}
pub struct ValueField<T:RetainedEquality>{cursor:T::Equality,project:fn(&DslValue)->Option<&T>,route:Option<(semio_framework_value_control_contract::OriginalEffectInvocationIdentity,usize,u64,usize,usize,semio_framework_value_control_contract::OriginalWorkActionBoundary)>}
impl<T:RetainedEquality> RetainedEqualityCursor<DslValue> for ValueField<T>{
 fn demand(&self,body:usize,work:u64)->Result<RetirementDemand,ValueError>{if work<2{return Ok(Default::default())}self.cursor.demand(body,work-2)}
 fn demand_admitted(&self,body:usize,work:u64)->Result<RetirementDemand,ValueError>{if work<2{return Ok(Default::default())}self.cursor.demand_admitted(body,work-2)}
 fn work_demand(&self,body:usize,work:u64)->Result<u64,ValueError>{if work<2{return Ok(0)}let child=self.cursor.work_demand(body,work-2)?;if child==0{return Ok(0)}child.checked_add(2).ok_or_else(invalid)}
 fn advance_into<'r>(&mut self,left:&DslValue,right:&DslValue,body:usize,work:u64,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,crate::RetainedEqualityStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,crate::RetainedEqualityStep,crate::OriginalRetirementFailure>,ValueError>{let invocation=effect.invocation().ok_or_else(invalid)?;if invocation.mode()!=semio_framework_value_control_contract::OriginalEffectCallbackMode::Receive||self.route.is_some(){return Err(invalid())}let identity=invocation.identity();let selected=match self.work_demand(body,work){Ok(v)=>v,Err(e)=>return Ok(reply.complete(Err(e.into())))};let demand=match self.demand(body,work){Ok(v)=>v,Err(e)=>return Ok(reply.complete(Err(e.into())))};if selected==0||effect.remaining_work_units()?<selected||!permits(effect.grant(),demand){return Ok(reply.complete(Ok(crate::RetainedEqualityStep{equal:None,progress:Default::default()})))}let boundary=effect.action_boundary();if !effect.performed(2)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"intrinsic projection exceeded original Work").into())))}let Some(l)=(self.project)(left)else{return Ok(reply.complete(Err(invalid().into())))};let Some(r)=(self.project)(right)else{return Ok(reply.complete(Err(invalid().into())))};let child_work=work-2;let remaining=child_work.min(effect.remaining_work_units()?);let mut child=effect.reborrow(effect.grant(),remaining)?;let key=(identity,body,work,left as *const _ as usize,right as *const _ as usize,boundary);let state=self;let mut scope=reply.scope(&mut state.route,key)?;let done=state.cursor.advance_into(l,r,body,child_work,&mut child,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn recover_advance_into<'r>(&mut self,left:&DslValue,right:&DslValue,body:usize,work:u64,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,crate::RetainedEqualityStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,crate::RetainedEqualityStep,crate::OriginalRetirementFailure>,ValueError>{let key=self.route.ok_or_else(invalid)?;let invocation=effect.invocation().ok_or_else(invalid)?;if invocation.mode()!=semio_framework_value_control_contract::OriginalEffectCallbackMode::Recover||invocation.identity()!=key.0||(body,work,left as *const _ as usize,right as *const _ as usize)!=(key.1,key.2,key.3,key.4){return Err(invalid())}let l=(self.project)(left).ok_or_else(invalid)?;let r=(self.project)(right).ok_or_else(invalid)?;let spent=effect.performed_since_action(key.5)?;let remaining=u128::from(work).checked_sub(spent).and_then(|n|u64::try_from(n).ok()).ok_or_else(invalid)?.min(effect.remaining_work_units()?);let mut child=effect.reborrow(effect.grant(),remaining)?;let state=self;let mut scope=reply.scope(&mut state.route,key)?;let done=state.cursor.recover_advance_into(l,r,body,work-2,&mut child,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn close_started(&self)->bool{self.cursor.close_started()}
 fn begin_close_demand(&self)->Result<RetirementDemand,ValueError>{self.cursor.begin_close_demand()}
 fn begin_close_work_demand(&self)->Result<u64,ValueError>{self.cursor.begin_close_work_demand()}
 fn begin_close_into<'r>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.cursor.begin_close_into(effect,reply)}
 fn recover_begin_close_into<'r>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.cursor.recover_begin_close_into(effect,reply)}
 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.cursor.close_demand(body)}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{self.cursor.close_work_demand(body)}
 fn close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.cursor.close_into(body,effect,reply)}
 fn recover_close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.cursor.recover_close_into(body,effect,reply)}
 fn terminal_is_empty(&self)->bool{self.route.is_none()&&self.cursor.terminal_is_empty()}
 fn requires_original_birth(&self)->bool{self.cursor.close_started()&&self.cursor.requires_original_birth()}
 fn close_original_birth_step(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->semio_framework_value_retirement_contract::OriginalRetirementPoll{self.cursor.close_original_birth_step(original,grant)}
 fn requires_original_control(&self)->bool{self.cursor.close_started()&&self.cursor.requires_original_control()}
 fn close_original_into<'r>(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.cursor.close_original_into(original,body,effect,reply.progress())}
 fn recover_close_original_into<'r>(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.cursor.recover_close_original_into(original,body,effect,reply.progress())}
 fn native_terminal_release(&self)->Option<semio_framework_value_native_clone_engine::RetainedCursorRelease<Self>>{let witness=self.cursor.native_terminal_release()?;if !self.route.is_none()||!witness.validates(&self.cursor){return None}Some(unsafe{semio_framework_value_native_clone_engine::RetainedCursorRelease::native(|owner:&Self|owner.route.is_none()&&owner.cursor.native_terminal_release().is_some_and(|witness|witness.validates(&owner.cursor)))})}
}
pub struct TextBirth;pub struct BytesBirth;pub struct ArrayBirth;pub struct ObjectBirth;
macro_rules! value_birth{($name:ident,$ty:ty,$project:ident)=>{unsafe impl RetainedEqualityBirth for $name{type Output=ValueField<$ty>;fn work()->Result<u64,ValueError>{<$ty as RetainedEquality>::CURSOR_BIRTH_WORK.checked_add(2).ok_or_else(invalid)}fn birth()->Self::Output{ValueField{cursor:<$ty as RetainedEquality>::equality_cursor(),project:$project,route:None}}}};}
value_birth!(TextBirth,String,text);value_birth!(BytesBirth,Vec<u8>,bytes);value_birth!(ArrayBirth,Vec<DslValue>,array);value_birth!(ObjectBirth,Vec<(String,DslValue)>,object);
fn field<B>(work:u64,g:RetainedCloneGrant,actual:&mut Option<usize>)->RetainedWorkOutcome<Option<(Box<dyn RetainedEqualityCursor<DslValue>>,RetainedCloneProgress)>> where B:RetainedEqualityBirth,B::Output:RetainedEqualityCursor<DslValue>+'static{let turn=equality_box::<B>(work,g,actual);RetainedWorkOutcome{work:turn.work,result:turn.result.map(|row|row.map(|(owner,p)|(owner as Box<dyn RetainedEqualityCursor<DslValue>>,p)))}}
fn text(value:&DslValue)->Option<&String>{match value{DslValue::String(value)=>Some(value),_=>None}}
fn bytes(value:&DslValue)->Option<&Vec<u8>>{match value{DslValue::Bytes(value)=>Some(value),_=>None}}
fn array(value:&DslValue)->Option<&Vec<DslValue>>{match value{DslValue::Array(value)=>Some(value),_=>None}}
fn object(value:&DslValue)->Option<&Vec<(String,DslValue)>>{match value{DslValue::Object(value)=>Some(value),_=>None}}
unsafe impl RetainedEquality for DslValue{
 type Equality=RetainedRecordEquality<Self>;
 const CURSOR_BIRTH_WORK:u64=7;
 const INLINE_PAIR_BYTES:Option<usize>=None;
 const INLINE_PAIR_WORK:Option<u64>=None;
 fn equality_cursor()->Self::Equality{RetainedRecordEquality::new()}
 fn inline_equal(_:&Self,_:&Self)->Option<bool>{None}
}
